            Spacer(Modifier.height(8.dp))

            Button(
                onClick = {
                    // TODO: call your AI backend here.
                    // For now just echo:
                    response = "AI (mock): You asked: \"$prompt\""
                },
                modifier = Modifier.align(Alignment.End)
            ) {
                Text("Send")
